static inline void llc_pdu_decode_dsap(struct sk_buff *skb, u8 *dsap) /* <=== llc_pdu_decode_dsap */ 
{
	*dsap = llc_pdu_un_hdr(skb)->dsap & 0xFE;
}

static void kfree_skbmem(struct sk_buff *skb) /* <=== kfree_skbmem */ 
{
	struct sk_buff *other;
	atomic_t *fclone_ref;

	switch (skb->fclone) {
	case SKB_FCLONE_UNAVAILABLE:
		kmem_cache_free(skbuff_head_cache, skb);
		break;

	case SKB_FCLONE_ORIG:
		fclone_ref = (atomic_t *) (skb + 2);
		if (atomic_dec_and_test(fclone_ref))
			kmem_cache_free(skbuff_fclone_cache, skb);
		break;

	case SKB_FCLONE_CLONE:
		fclone_ref = (atomic_t *) (skb + 1);
		other = skb - 1;

		/* The clone portion is available for
		 * fast-cloning again.
		 */
		skb->fclone = SKB_FCLONE_UNAVAILABLE;

		if (atomic_dec_and_test(fclone_ref))
			kmem_cache_free(skbuff_fclone_cache, other);
		break;
	}
}

void *memcpy(void *to, const void *from, __kernel_size_t n) /* <=== memcpy */ 
{
	if (n < LARGE_COPY_CUTOFF)
		return (void *)__memcpy_asm(to, from, n);
	else
		return (void *)fast_copy(to, from, n, __memcpy_asm);
}

static inline struct llc_sock *llc_sk(const struct sock *sk) /* <=== llc_sk */ 
{
	return (struct llc_sock *)sk;
}

static inline void spin_lock_bh(spinlock_t *lock) /* <=== spin_lock_bh */ 
{
	raw_spin_lock_bh(&lock->rlock);
}

static void skb_release_all(struct sk_buff *skb) /* <=== skb_release_all */ 
{
	skb_release_head_state(skb);
	skb_release_data(skb);
}

static inline struct ethhdr *eth_hdr(const struct sk_buff *skb) /* <=== eth_hdr */ 
{
	return (struct ethhdr *)skb_mac_header(skb);
}

static inline void sk_eat_skb(struct sock *sk, struct sk_buff *skb, bool copied_early) /* <=== sk_eat_skb */ 
{
	__skb_unlink(skb, &sk->sk_receive_queue);
	__kfree_skb(skb);
}

static inline void llc_pdu_decode_da(struct sk_buff *skb, u8 *da) /* <=== llc_pdu_decode_da */ 
{
	if (skb->protocol == htons(ETH_P_802_2))
		memcpy(da, eth_hdr(skb)->h_dest, ETH_ALEN);
}

void release_sock(struct sock *sk) /* <=== release_sock */ 
{
	/*
	 * The sk_lock has mutex_unlock() semantics:
	 */
	mutex_release(&sk->sk_lock.dep_map, 1, _RET_IP_);

	spin_lock_bh(&sk->sk_lock.slock);
	if (sk->sk_backlog.tail)
		__release_sock(sk);

	if (sk->sk_prot->release_cb)
		sk->sk_prot->release_cb(sk);

	sk->sk_lock.owned = 0;
	if (waitqueue_active(&sk->sk_lock.wq))
		wake_up(&sk->sk_lock.wq);
	spin_unlock_bh(&sk->sk_lock.slock);
}

void *memcpy(void *dest, const void *src, size_t n) /* <=== memcpy */ 
{
	long d0, d1, d2;
	asm volatile(
		"rep ; movsq\n\t"
		"movq %4,%%rcx\n\t"
		"rep ; movsb\n\t"
		: "=&c" (d0), "=&D" (d1), "=&S" (d2)
		: "0" (n >> 3), "g" (n & 7), "1" (dest), "2" (src)
		: "memory");

	return dest;
}

static void llc_cmsg_rcv(struct msghdr *msg, struct sk_buff *skb) /* <=== llc_cmsg_rcv */ 
{
	struct llc_sock *llc = llc_sk(skb->sk);

	if (llc->cmsg_flags & LLC_CMSG_PKTINFO) {
		struct llc_pktinfo info;

		info.lpi_ifindex = llc_sk(skb->sk)->dev->ifindex;
		llc_pdu_decode_dsap(skb, &info.lpi_sap);
		llc_pdu_decode_da(skb, info.lpi_mac);
		put_cmsg(msg, SOL_LLC, LLC_OPT_PKTINFO, sizeof(info), &info);
	}
}

static inline struct llc_pdu_un *llc_pdu_un_hdr(struct sk_buff *skb) /* <=== llc_pdu_un_hdr */ 
{
	return (struct llc_pdu_un *)skb_network_header(skb);
}

int put_cmsg(struct msghdr * msg, int level, int type, int len, void *data) /* <=== put_cmsg */ 
{
	struct cmsghdr __user *cm
		= (__force struct cmsghdr __user *)msg->msg_control;
	struct cmsghdr cmhdr;
	int cmlen = CMSG_LEN(len);
	int err;

	if (MSG_CMSG_COMPAT & msg->msg_flags)
		return put_cmsg_compat(msg, level, type, len, data);

	if (cm==NULL || msg->msg_controllen < sizeof(*cm)) {
		msg->msg_flags |= MSG_CTRUNC;
		return 0; /* XXX: return error? check spec. */
	}
	if (msg->msg_controllen < cmlen) {
		msg->msg_flags |= MSG_CTRUNC;
		cmlen = msg->msg_controllen;
	}
	cmhdr.cmsg_level = level;
	cmhdr.cmsg_type = type;
	cmhdr.cmsg_len = cmlen;

	err = -EFAULT;
	if (copy_to_user(cm, &cmhdr, sizeof cmhdr))
		goto out;
	if (copy_to_user(CMSG_DATA(cm), data, cmlen - sizeof(struct cmsghdr)))
		goto out;
	cmlen = CMSG_SPACE(len);
	if (msg->msg_controllen < cmlen)
		cmlen = msg->msg_controllen;
	msg->msg_control += cmlen;
	msg->msg_controllen -= cmlen;
	err = 0;
out:
	return err;
}

static inline void spin_unlock_bh(spinlock_t *lock) /* <=== spin_unlock_bh */ 
{
	raw_spin_unlock_bh(&lock->rlock);
}

